WITH src AS (SELECT * FROM order_items WHERE product_id IS NULL), unit_price_bucket_summary AS (SELECT CASE WHEN unit_price >= 400 THEN 'high' WHEN unit_price >= 90 THEN 'mid' ELSE 'low' END AS unit_price_bucket, MAX(quantity) AS max_quantity FROM src GROUP BY CASE WHEN unit_price >= 400 THEN 'high' WHEN unit_price >= 90 THEN 'mid' ELSE 'low' END) SELECT unit_price_bucket, max_quantity FROM unit_price_bucket_summary;
